      out.write("        <section class=\"col-md-8\">\n");
      out.write("          <h2>ATRSについて</h2>\n");
      out.write("\n");
      out.write("          <section>\n");
      out.write("            <h3>概要</h3>\n");
      out.write("            <p>\n");
      out.write("              ATRS（本アプリケーション）は、Macchinetta オンライン版 フレームワーク、Macchinetta クライアント基本版 フレームワーク（以下、フレームワーク）を用いたサンプルアプリケーションです。\n");
      out.write("            </p>\n");
      out.write("            <dl>\n");
      out.write("              <dt>バージョン</dt>\n");
      out.write("              <dd>1.8.1</dd>\n");
      out.write("            </dl>\n");
      out.write("          </section>\n");
      out.write("\n");
      out.write("          <section>\n");
      out.write("            <h3>ATRSの利用方法</h3>\n");
      out.write("            <ul>\n");
      out.write("              <li>ATRSにログインする場合は、ログインボタンを押して、会員番号とパスワードを入力してログインしてください。</li>\n");
      out.write("              <li>ATRSからログアウトする場合は、ログインユーザメニューからログアウトを選択してください。</li>\n");
